UPDATE notifications
SET is_read = true, read_at = NOW()
WHERE id=#{id} AND receiver_id=#{receiverId}

mapper.select:
SELECT * FROM notifications
WHERE receiver_id = #{receiverId} AND event_key = #{eventKey}
LIMIT 1

SELECT id FROM notifications
WHERE receiver_id = #{receiverId} AND event_key = #{eventKey}
LIMIT 1

SELECT EXISTS (
    SELECT true FROM notification_deliveries
    WHERE notification_id = #{notificationId}
    LIMIT 1
)

SELECT COUNT(*)
FROM notification_deliveries
WHERE notification_id = #{notificationId}

SELECT * FROM notifications n WHERE n.notification_type IN ('COUPON', 'COUPON_EXPIRING_SOON') AND n.delivery_scope = 'WEB_AND_SMS' AND n.created_at >= DATE_SUB(NOW(), INTERVAL 2 HOUR)
AND n.id > #{lastId}
AND NOT EXISTS ( SELECT 1 FROM notification_deliveries nd WHERE nd.notification_id = n.id AND nd.status IN ('SENT', 'DELIVERED') ) AND ( SELECT COUNT(*) FROM notification_deliveries nd2 WHERE nd2.notification_id = n.id ) < 2 AND NOT EXISTS ( SELECT 1 FROM notification_deliveries nd3 WHERE nd3.notification_id = n.id AND nd3.status = 'PENDING' AND nd3.created_at >= DATE_SUB(NOW(), INTERVAL 1 MINUTE) ) ORDER BY n.id ASC LIMIT #{limit}
